{
  "items": [
    {
      "name": "Real.rpow_le_of_le_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 0 < y → Real.log x ≤ z * Real.log y → x ≤ y ^ z"
    },
    {
      "name": "Real.rpow_lt_of_lt_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y z : ℝ}, 0 < y → Real.log x < z * Real.log y → x < y ^ z"
    },
    {
      "name": "Real.pow_lt_of_lt_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < y → Real.log x < ↑n * Real.log y → x < y ^ n"
    },
    {
      "name": "Real.lt_pow_of_log_lt",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < y → Real.log x < ↑n * Real.log y → x < y ^ n"
    },
    {
      "name": "Real.le_pow_iff_log_le",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Pow.Real",
      "kind": "theorem",
      "type": "∀ {x y : ℝ} {n : ℕ}, 0 < x → 0 < y → (x ≤ y ^ n ↔ Real.log x ≤ ↑n * Real.log y)"
    }
  ]
}
